mapper.select:
select note_id, note_title, note_content, sort, status, create_time
from note
where note_id = #{noteId}

mapper.update:
update note
set note_title = #{noteTitle}, note_content = #{noteContent}, sort = #{sort}
where note_id = #{noteId}

update note
set status = #{status}
where note_id = #{noteId}
